window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-XXXXXXXXXX');

head.b:skin:
:root {
    --bg-color: #080b11;
    --card-bg: rgba(17, 24, 39, 0.75);
    --text-main: #ffffff;
    --text-sub: #94a3b8;
    --accent-color: #38bdf8;
    --accent-gradient: linear-gradient(135deg, #3b82f6, #06b6d4);
    --border-color: rgba(255, 255, 255, 0.08);
    --base-font-size: 16px;
    --main-font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, sans-serif;
    --glass-blur: 12px;
    --custom-bg-image: none;
}

html, body {
    margin: 0;
    padding: 0;
    width: 100%;
}

body.theme-sakura {
    --bg-color: #1a0f18;
    --card-bg: rgba(42, 22, 37, 0.75);
    --text-main: #fce7f3;
    --text-sub: #f472b6;
    --accent-color: #ec4899;
    --accent-gradient: linear-gradient(135deg, #ec4899, #f43f5e);
    --border-color: rgba(236, 72, 153, 0.15);
}

body.theme-cyberpunk {
    --bg-color: #09090e;
    --card-bg: rgba(22, 22, 37, 0.8);
    --text-main: #00ffcc;
    --text-sub: #ff0055;
    --accent-color: #ff0055;
    --accent-gradient: linear-gradient(135deg, #ff0055, #00ffcc);
    --border-color: rgba(0, 255, 204, 0.2);
}

body.theme-emerald {
    --bg-color: #061512;
    --card-bg: rgba(12, 39, 34, 0.75);
    --text-main: #ecfdf5;
    --text-sub: #6ee7b7;
    --accent-color: #10b981;
    --accent-gradient: linear-gradient(135deg, #10b981, #059669);
    --border-color: rgba(16, 185, 129, 0.15);
}

body.theme-sunset {
    --bg-color: #180e0a;
    --card-bg: rgba(41, 24, 17, 0.75);
    --text-main: #ffedd5;
    --text-sub: #fdba74;
    --accent-color: #f97316;
    --accent-gradient: linear-gradient(135deg, #f97316, #eab308);
    --border-color: rgba(249, 115, 22, 0.15);
}

body.light-mode {
    --bg-color: #f7f4ed;
    --card-bg: rgba(255, 255, 255, 0.85);
    --text-main: #1e293b;
    --text-sub: #64748b;
    --border-color: rgba(0, 0, 0, 0.08);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: var(--main-font-family);
    -webkit-tap-highlight-color: transparent;
}

html { scroll-behavior: smooth; font-size: var(--base-font-size); }

body {
    background-color: var(--bg-color);
    background-image: var(--custom-bg-image);
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    overflow-x: hidden;
    position: relative;
    transition: background 0.3s ease, color 0.3s ease;
}

header {
    width: 100%;
    max-width: 480px;
    padding: 16px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--bg-color);
    backdrop-filter: blur(var(--glass-blur));
    position: sticky;
    top: 0;
    z-index: 100;
    border-bottom: 1px solid var(--border-color);
}

.logo { font-size: 1.25rem; font-weight: 800; color: var(--text-main); letter-spacing: -0.5px; }
.logo span { color: var(--accent-color); }

.menu-btn {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--border-color);
    border-radius: 10px;
    width: 40px;
    height: 40px;
    color: var(--text-main);
    font-size: 1.1rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.2s ease;
}

.menu-btn:active { transform: scale(0.85); }

.dropdown-menu {
    position: absolute;
    top: 65px;
    right: 20px;
    width: 280px;
    max-height: 80vh;
    overflow-y: auto;
    background: var(--card-bg);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 14px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
    display: flex;
    flex-direction: column;
    gap: 6px;
    opacity: 0;
    visibility: hidden;
    transform-origin: top right;
    transform: translateY(-15px) scale(0.8);
    transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55), visibility 0.3s ease;
    z-index: 200;
}

.dropdown-menu.active {
    opacity: 1;
    visibility: visible;
    transform: translateY(0) scale(1);
}

.dropdown-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 9px 12px;
    color: var(--text-main);
    text-decoration: none;
    font-size: 0.85rem;
    font-weight: 600;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.03);
    border: none;
    cursor: pointer;
    text-align: left;
    transition: background 0.2s ease;
    width: 100%;
}
.dropdown-item:hover { background: rgba(56, 189, 248, 0.15); }
.dropdown-item-left { display: flex; align-items: center; gap: 10px; }
.dropdown-item i { color: var(--accent-color); font-size: 0.95rem; width: 18px; text-align: center; }

.menu-divider { height: 1px; background: var(--border-color); margin: 4px 0; }
.menu-title { font-size: 0.7rem; color: var(--text-sub); text-transform: uppercase; letter-spacing: 0.5px; margin: 4px 0 2px 4px; font-weight: 700; }

.preset-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 6px;
    margin-top: 4px;
}

.preset-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    border-radius: 8px;
    border: 1px solid var(--border-color);
    background: rgba(255, 255, 255, 0.03);
    color: var(--text-main);
    font-size: 0.75rem;
    font-weight: 600;
    cursor: pointer;
    transition: 0.2s;
}

.preset-badge { width: 12px; height: 12px; border-radius: 50%; display: inline-block; }
.btn-group-sm { display: flex; gap: 4px; flex-wrap: wrap; }
.btn-sm {
    padding: 4px 8px;
    font-size: 0.72rem;
    border-radius: 6px;
    border: 1px solid var(--border-color);
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-main);
    cursor: pointer;
}

.container {
    width: 100%;
    max-width: 480px;
    padding: 24px 20px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.profile-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin-bottom: 35px;
    width: 100%;
}

.avatar-wrapper {
    position: relative;
    width: 130px;
    height: 130px;
    border-radius: 50%;
    padding: 5px;
    margin-bottom: 16px;
    background: rgba(30, 41, 59, 0.6);
    border: 2px solid var(--accent-color);
    box-shadow: 0 0 25px rgba(56, 189, 248, 0.2);
    display: flex;
    align-items: center;
    justify-content: center;
}

.avatar-img {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
    background-color: #0f172a;
}

.email-box {
    background: var(--card-bg);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 8px 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.85rem;
    color: var(--text-sub);
    margin-bottom: 18px;
}

.copy-btn {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid var(--border-color);
    color: var(--text-main);
    padding: 4px 8px;
    border-radius: 6px;
    cursor: pointer;
}

.profile-title { font-size: 1.5rem; font-weight: 800; line-height: 1.3; margin-bottom: 6px; }
.profile-title .highlight { color: var(--accent-color); }

.typing-text-container {
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--text-sub);
    margin-bottom: 12px;
    min-height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.typing-text { color: var(--text-main); }
.cursor { display: inline-block; width: 2px; height: 1.1em; background-color: var(--accent-color); margin-left: 3px; animation: blink 0.8s infinite; }
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }

.profile-bio { color: var(--text-sub); font-size: 0.88rem; margin-bottom: 18px; }
.profile-buttons { display: flex; gap: 12px; width: 100%; max-width: 320px; }
.btn-primary { flex: 1; background: var(--accent-gradient); color: #fff; padding: 10px; border-radius: 10px; font-weight: 600; text-decoration: none; font-size: 0.88rem; text-align: center; border: none; }
.btn-secondary { flex: 1; background: transparent; border: 1px solid var(--border-color); color: var(--text-main); padding: 10px; border-radius: 10px; font-weight: 600; text-decoration: none; font-size: 0.88rem; text-align: center; }

.section-box { width: 100%; margin-bottom: 35px; }
.section-header-box { display: flex; flex-direction: column; gap: 10px; margin-bottom: 16px; }
.section-title { font-size: 1.25rem; font-weight: 800; letter-spacing: -0.3px; }
.section-sub { color: var(--text-sub); font-size: 0.8rem; margin-top: 2px; }

/* === SEARCH BAR === */
.search-box-container {
    position: relative;
    width: 100%;
    margin-top: 6px;
}

.search-input {
    width: 100%;
    background: var(--card-bg);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 10px 14px 10px 38px;
    color: var(--text-main);
    font-size: 0.85rem;
    outline: none;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.search-input:focus {
    border-color: var(--accent-color);
    box-shadow: 0 0 15px rgba(56, 189, 248, 0.2);
}

.search-icon-inside {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-sub);
    font-size: 0.9rem;
}

/* === TAMPILAN GRID GALERI 4 KOLOM === */
.gallery-grid-container {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
    width: 100%;
}

.gallery-card {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 1;
    border-radius: 10px;
    overflow: hidden;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    cursor: pointer;
    transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.gallery-card:hover, .gallery-card:active {
    transform: scale(0.96);
    border-color: var(--accent-color);
    box-shadow: 0 0 12px rgba(56, 189, 248, 0.4);
    z-index: 2;
}

.gallery-thumb {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

/* Overlay Informasi Teks saat Hover/Tap */
.gallery-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, transparent 60%);
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: 6px;
    opacity: 0;
    transition: opacity 0.25s ease;
}

.gallery-card:hover .gallery-overlay, .gallery-card:active .gallery-overlay {
    opacity: 1;
}

.gallery-title {
    font-size: 0.65rem;
    font-weight: 700;
    color: #fff;
    line-height: 1.2;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.gallery-badge {
    position: absolute;
    top: 4px;
    right: 4px;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    color: #fff;
    font-size: 0.55rem;
    font-weight: 700;
    padding: 2px 5px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    gap: 3px;
}

/* MODAL & COMMENTS */
.post-modal-overlay {
    position: fixed;
    top: 0; left: 0; width: 100vw; height: 100vh;
    background: rgba(8, 11, 17, 0.85);
    backdrop-filter: blur(8px);
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.3s ease, visibility 0.3s ease;
}

.post-modal-overlay.active { opacity: 1; visibility: visible; }

.post-modal-container {
    background: var(--card-bg);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--border-color);
    border-radius: 20px;
    width: 100%;
    max-width: 480px;
    max-height: 85vh;
    overflow-y: auto;
    padding: 24px;
    position: relative;
    box-shadow: 0 20px 40px rgba(0,0,0,0.6);
    transform: scale(0.85);
    transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.post-modal-overlay.active .post-modal-container { transform: scale(1); }

.post-modal-close {
    position: absolute;
    top: 16px; right: 16px;
    width: 32px; height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.08);
    border: none;
    color: var(--text-main);
    font-size: 1rem;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
}

.post-modal-title { font-size: 1.25rem; font-weight: 800; color: var(--text-main); margin-bottom: 12px; padding-right: 30px; }
.post-modal-body { font-size: 0.88rem; color: var(--text-sub); line-height: 1.6; word-break: break-word; }
.post-modal-body img { max-width: 100%; height: auto; border-radius: 12px; margin: 12px 0; }

.modal-action-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 20px;
    padding-top: 15px;
    border-top: 1px dashed var(--border-color);
    gap: 8px;
    flex-wrap: wrap;
}

.action-btn-group { display: flex; gap: 6px; align-items: center; }

.share-love-btn {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--border-color);
    color: var(--text-main);
    padding: 6px 12px;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    text-decoration: none;
}

.comments-section { margin-top: 15px; padding-top: 15px; border-top: 1px solid var(--border-color); }
.comments-title { font-size: 1rem; font-weight: 700; margin-bottom: 12px; color: var(--text-main); }

.comment-input-box { display: flex; flex-direction: column; gap: 8px; margin-bottom: 15px; }
.comment-input-box input, .comment-input-box textarea {
    width: 100%;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 8px 12px;
    color: var(--text-main);
    font-size: 0.82rem;
    outline: none;
}
.comment-input-box textarea { resize: vertical; min-height: 60px; }

.comment-submit-btn {
    align-self: flex-end;
    background: var(--accent-gradient);
    color: #fff;
    border: none;
    padding: 6px 14px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.8rem;
    cursor: pointer;
}

.comments-list { display: flex; flex-direction: column; gap: 10px; max-height: 220px; overflow-y: auto; }
.comment-item { background: rgba(255, 255, 255, 0.02); border: 1px solid var(--border-color); border-radius: 8px; padding: 10px 12px; font-size: 0.8rem; }
.comment-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
.comment-author { font-weight: 700; color: var(--accent-color); }
.comment-actions { display: flex; gap: 8px; }
.comment-action-btn { background: transparent; border: none; color: var(--text-sub); font-size: 0.75rem; cursor: pointer; }
.comment-text { color: var(--text-main); line-height: 1.4; word-break: break-word; }
.comment-time { font-size: 0.7rem; color: var(--text-sub); margin-top: 4px; }

.recent-dialog-item {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    text-align: left;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.recent-dialog-author { font-weight: 700; font-size: 0.82rem; color: var(--accent-color); display: flex; align-items: center; gap: 6px; }
.recent-dialog-text { font-size: 0.83rem; color: var(--text-main); line-height: 1.4; word-break: break-word; }
.recent-dialog-post { font-size: 0.74rem; color: var(--text-sub); display: inline-flex; align-items: center; gap: 6px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

.custom-input-sm {
    width: 100%;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 5px 8px;
    color: var(--text-main);
    font-size: 0.75rem;
    outline: none;
}

.main { display: none !important; }

.links-list { width: 100%; display: flex; flex-direction: column; gap: 14px; margin-top: 15px; }

.link-card {
    position: relative;
    background: var(--card-bg);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--border-color);
    border-radius: 14px;
    padding: 16px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    text-decoration: none;
    color: var(--text-main);
    overflow: hidden;
    z-index: 1;
}

.card-left { display: flex; align-items: center; gap: 14px; }
.icon-box {
    width: 40px; height: 40px; border-radius: 10px;
    background: rgba(59, 130, 246, 0.15); color: var(--accent-color);
    display: flex; align-items: center; justify-content: center; font-size: 1.1rem;
}
.card-info h3 { font-size: 0.92rem; font-weight: 600; margin-bottom: 2px; }
.card-info p { font-size: 0.75rem; color: var(--text-sub); }
.arrow-icon { color: var(--text-sub); font-size: 0.85rem; }

.social-links { display: flex; justify-content: center; gap: 10px; margin-top: 15px; }
.social-icon {
    width: 38px; height: 38px; border-radius: 8px;
    background: rgba(255, 255, 255, 0.03); border: 1px solid var(--border-color);
    display: flex; align-items: center; justify-content: center; color: var(--text-sub); text-decoration: none;
}

.traffic-card {
    width: 100%; background: var(--card-bg);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--border-color);
    border-radius: 16px; padding: 20px; margin-bottom: 40px;
}
.badge-live { display: inline-flex; align-items: center; gap: 6px; color: var(--accent-color); font-size: 0.8rem; font-weight: 600; margin-bottom: 12px; }

.stat-grid-top {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    text-align: center;
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border-color);
}

.stat-box-item .num { font-size: 1.1rem; font-weight: 800; color: var(--accent-color); }
.stat-box-item .lbl { font-size: 0.72rem; color: var(--text-sub); margin-top: 2px; }

.stat-list-detail { display: flex; flex-direction: column; gap: 8px; }
.stat-row { display: flex; justify-content: space-between; align-items: center; font-size: 0.82rem; color: var(--text-sub); }
.stat-row span.val { font-weight: 700; color: var(--text-main); }

footer { text-align: center; font-size: 0.75rem; color: var(--text-sub); padding-bottom: 30px; line-height: 1.6; }

.touch-container { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: 9999; }
.touch-ring {
    position: absolute; width: 30px; height: 30px; border: 2px solid var(--accent-color); border-radius: 50%;
    transform: translate(-50%, -50%) scale(0.3); opacity: 0;
    animation: ringExpand 0.7s ease-out forwards;
}
@keyframes ringExpand {
    0% { transform: translate(-50%, -50%) scale(0.2); opacity: 0; }
    30% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(2.2); opacity: 0; }
}

.falling-particle {
    position: fixed;
    top: -30px;
    pointer-events: none;
    z-index: 99;
    animation: fall linear infinite;
}
@keyframes fall { to { transform: translateY(105vh) rotate(360deg); } }

.scroll-reveal {
    opacity: 0;
    transform: translateY(35px) scale(0.92);
    transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), opacity 0.5s ease-out;
}

.scroll-reveal.revealed { opacity: 1; transform: translateY(0) scale(1); }

body.script:
//
  const FORMSPREE_ENDPOINT_ID = 'mvkzpprq';

  let particleInterval;
  let currentAnimType = localStorage.getItem('bgAnimType') || 'leaf';
  let particleSpeed = parseInt(localStorage.getItem('bgAnimSpeed')) || 300;
  let currentActivePostId = '';
  let editingCommentIndex = null;
  let isBubblesOn = localStorage.getItem('bubbles_enabled') !== 'false';
  let allPostsData = [];

  document.addEventListener("DOMContentLoaded", function () {
      const savedPreset = localStorage.getItem('themePreset');
      if (savedPreset) applyThemePreset(savedPreset, false);

      const savedFontSize = localStorage.getItem('fontSize');
      if (savedFontSize) document.documentElement.style.setProperty('--base-font-size', savedFontSize);

      const savedFontFamily = localStorage.getItem('fontFamily');
      if (savedFontFamily) setFontFamily(savedFontFamily, false);

      const savedCustomBg = localStorage.getItem('custom_bg_val');
      if (savedCustomBg) {
          if (savedCustomBg.startsWith('http') || savedCustomBg.startsWith('data:image')) {
              document.body.style.backgroundImage = `url('${savedCustomBg}')`;
          } else {
              document.body.style.background = savedCustomBg;
          }
      }

      const savedBlur = localStorage.getItem('glass_blur_val');
      if (savedBlur) document.documentElement.style.setProperty('--glass-blur', savedBlur);

      setBgAnimation(isBubblesOn ? currentAnimType : 'none', false);
      syncBubbleUI();
      initLikesAndStats();
      syncFollowUI();
  });

  function setCustomBgColor(colorVal) {
      document.body.style.backgroundImage = 'none';
      document.body.style.backgroundColor = colorVal;
      localStorage.setItem('custom_bg_val', colorVal);
  }

  function setGradientBg(gradientStr) {
      document.body.style.backgroundImage = 'none';
      document.body.style.background = gradientStr;
      localStorage.setItem('custom_bg_val', gradientStr);
  }

  function setBgUrlFromInput() {
      const url = document.getElementById('bgUrlInput').value.trim();
      if (!url) return;
      document.body.style.backgroundImage = `url('${url}')`;
      localStorage.setItem('custom_bg_val', url);
  }

  function handleBgFileUpload(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
          const dataUrl = e.target.result;
          document.body.style.backgroundImage = `url('${dataUrl}')`;
          localStorage.setItem('custom_bg_val', dataUrl);
      };
      reader.readAsDataURL(file);
  }

  function resetCustomBg() {
      localStorage.removeItem('custom_bg_val');
      document.body.style.backgroundImage = 'none';
      const savedPreset = localStorage.getItem('themePreset') || 'default';
      applyThemePreset(savedPreset, false);
  }

  function setGlassBlur(blurVal) {
      document.documentElement.style.setProperty('--glass-blur', blurVal);
      localStorage.setItem('glass_blur_val', blurVal);
  }

  function toggleBubbles() {
      isBubblesOn = !isBubblesOn;
      localStorage.setItem('bubbles_enabled', isBubblesOn);
      syncBubbleUI();
      setBgAnimation(isBubblesOn ? currentAnimType : 'none', true);
  }

  function syncBubbleUI() {
      const statusEl = document.getElementById('bubbleStatus');
      if (statusEl) {
          statusEl.innerText = isBubblesOn ? 'ON' : 'OFF';
          statusEl.style.color = isBubblesOn ? '#10b981' : 'var(--text-sub)';
      }
  }

  function setFontFamily(type, save = true) {
      let fontStack = "'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, sans-serif";
      if (type === 'serif') fontStack = "Georgia, 'Times New Roman', Times, serif";
      else if (type === 'mono') fontStack = "'Fira Code', Consolas, 'Courier New', monospace";
      else if (type === 'cursive') fontStack = "'Comic Sans MS', 'Chalkboard SE', 'Comic Neue', cursive";

      document.documentElement.style.setProperty('--main-font-family', fontStack);
      if (save) localStorage.setItem('fontFamily', type);
  }

  function applyThemePreset(presetName, save = true) {
      document.body.classList.remove('theme-sakura', 'theme-cyberpunk', 'theme-emerald', 'theme-sunset', 'light-mode');
      if (presetName === 'sakura') document.body.classList.add('theme-sakura');
      else if (presetName === 'cyberpunk') document.body.classList.add('theme-cyberpunk');
      else if (presetName === 'emerald') document.body.classList.add('theme-emerald');
      else if (presetName === 'sunset') document.body.classList.add('theme-sunset');
      else if (presetName === 'light') document.body.classList.add('light-mode');

      if (save) localStorage.setItem('themePreset', presetName);
  }

  function toggleThemeMode() {
      const isLight = document.body.classList.contains('light-mode');
      applyThemePreset(isLight ? 'default' : 'light');
  }

  function toggleMenu() {
      const menu = document.getElementById('dropdownMenu');
      if (menu.classList.contains('active')) closeMenu();
      else {
          menu.classList.remove('closing');
          menu.classList.add('active');
      }
  }

  function closeMenu() {
      const menu = document.getElementById('dropdownMenu');
      if (menu.classList.contains('active')) {
          menu.classList.remove('active');
          menu.classList.add('closing');
          setTimeout(() => menu.classList.remove('closing'), 300);
      }
  }

  window.addEventListener('click', function(e) {
      const menu = document.getElementById('dropdownMenu');
      const button = document.getElementById('menuToggle');
      if (!menu.contains(e.target) && !button.contains(e.target)) closeMenu();
  });

  function updateClock() {
      const now = new Date();
      const clockEl = document.getElementById('liveClock');
      if (clockEl) clockEl.innerText = now.toLocaleTimeString();
  }
  setInterval(updateClock, 1000);
  updateClock();

  /* --- MENGAMBIL DATA FEED BLOGGER --- */
  document.addEventListener("DOMContentLoaded", function () {
      fetch('/feeds/posts/default?alt=json&max-results=50')
          .then(response => response.json())
          .then(data => {
              const entries = data.feed.entry || [];
              document.getElementById('totalPosts').innerText = entries.length;

              allPostsData = entries.map((entry, idx) => {
                  const title = entry.title.$t;
                  const body = entry.content ? entry.content.$t : (entry.summary ? entry.summary.$t : '');
                  const postId = entry.id.$t.split('post-')[1] || ('post_' + idx);
                  const isLatestPost = (idx === 0);

                  let imgSrc = 'https://via.placeholder.com/300x300/1e293b/ffffff?text=GNZX';
                  if (entry.media$thumbnail) {
                      imgSrc = entry.media$thumbnail.url.replace('/s72-c/', '/w600/');
                  } else {
                      const tempDiv = document.createElement('div');
                      tempDiv.innerHTML = body;
                      const img = tempDiv.querySelector('img');
                      if (img) imgSrc = img.src;
                  }

                  const tempDiv = document.createElement('div');
                  tempDiv.innerHTML = body;
                  const cleanText = tempDiv.textContent || tempDiv.innerText || '';

                  return {
                      postId,
                      title,
                      body,
                      imgSrc,
                      isLatestPost,
                      cleanText: cleanText.toLowerCase()
                  };
              });

              renderGalleryGrid(allPostsData);
              updateTotalCommentsCount();
          })
          .catch(err => {
              console.error("Error loading feed:", err);
              document.getElementById('galleryGrid').innerHTML = `<div style="grid-column: 1 / -1; text-align:center; padding:20px; color:var(--text-sub);">Gagal memuat galeri.</div>`;
          });
  });

  /* --- RENDERING STYLE GRID GALERI 4 KOLOM --- */
  function renderGalleryGrid(posts) {
      const grid = document.getElementById('galleryGrid');
      if (!grid) return;
      grid.innerHTML = '';

      if (posts.length === 0) {
          grid.innerHTML = `
              <div style="grid-column: 1 / -1; text-align:center; padding:40px 10px; color:var(--text-sub);">
                  <i class="fa-solid fa-magnifying-glass" style="font-size:2rem; margin-bottom:10px; opacity:0.5;"></i>
                  <p style="font-size:0.85rem;">Tidak ada foto/postingan yang cocok.</p>
              </div>`;
          return;
      }

      posts.forEach(post => {
          const card = document.createElement('div');
          card.className = 'gallery-card';
          card.setAttribute('data-postid', post.postId);
          card.setAttribute('data-title', post.title);

          card.innerHTML = `
              <img class="gallery-thumb" src="${post.imgSrc}" alt="${post.title}"/>
              ${post.isLatestPost ? `<div class="gallery-badge"><i class="fa-solid fa-fire" style="color:#ef4444;"></i> NEW</div>` : ''}
              <div class="gallery-overlay">
                  <div class="gallery-title">${post.title}</div>
              </div>
          `;

          card.onclick = function() {
              openPostModal(post.postId, post.title, post.body);
          };

          grid.appendChild(card);
      });
  }

  /* --- FUNGSI FILTER PENCARIAN REAL-TIME --- */
  function filterPostsBySearch() {
      const query = document.getElementById('searchInput').value.toLowerCase().trim();
      if (!query) {
          renderGalleryGrid(allPostsData);
          return;
      }

      const filtered = allPostsData.filter(post => {
          return post.title.toLowerCase().includes(query) || post.cleanText.includes(query);
      });

      renderGalleryGrid(filtered);
  }

  function toggleFollowGlobal(e) {
      if (e) e.stopPropagation();
      let isFollowing = localStorage.getItem('is_following_blog') === 'true';
      isFollowing = !isFollowing;

      localStorage.setItem('is_following_blog', isFollowing ? 'true' : 'false');

      let baseFollowers = parseInt(localStorage.getItem('bg_base_followers') || '10');
      let currentFollowerCount = isFollowing ? (baseFollowers + 1) : baseFollowers;
      localStorage.setItem('bg_total_followers', currentFollowerCount);

      syncFollowUI();
  }

  function syncFollowUI() {
      const isFollowing = localStorage.getItem('is_following_blog') === 'true';
      const followerCount = localStorage.getItem('bg_total_followers') || '10';

      const totalFollowersEl = document.getElementById('totalFollowers');
      if(totalFollowersEl) totalFollowersEl.innerText = followerCount;

      const modalBtn = document.getElementById('modalFollowBtn');
      const modalIcon = document.getElementById('modalFollowIcon');
      const modalText = document.getElementById('modalFollowText');

      if (modalBtn) {
          if (isFollowing) modalBtn.classList.add('following');
          else modalBtn.classList.remove('following');
      }
      if (modalIcon) modalIcon.className = `fa-solid fa-${isFollowing ? 'user-check' : 'user-plus'}`;
      if (modalText) modalText.innerText = isFollowing ? 'Mengikuti' : 'Ikuti';
  }

  function toggleLike(e, postId) {
      if(e) e.stopPropagation();
      let likesData = JSON.parse(localStorage.getItem('post_likes_data') || '{}');
      if (!likesData[postId]) likesData[postId] = { count: 0, userLiked: false };

      if (likesData[postId].userLiked) {
          likesData[postId].count = Math.max(0, likesData[postId].count - 1);
          likesData[postId].userLiked = false;
      } else {
          likesData[postId].count += 1;
          likesData[postId].userLiked = true;
      }

      localStorage.setItem('post_likes_data', JSON.stringify(likesData));
      syncLikeUI(postId);
  }

  function toggleLikeFromModal(e) {
      if(currentActivePostId) {
          toggleLike(e, currentActivePostId);
      }
  }

  function syncLikeUI(postId) {
      const likesData = JSON.parse(localStorage.getItem('post_likes_data') || '{}');
      const isLiked = likesData[postId] ? likesData[postId].userLiked : false;
      const count = likesData[postId] ? likesData[postId].count : 0;

      if (currentActivePostId === postId) {
          const modalBtn = document.getElementById('modalLikeBtn');
          const modalIcon = document.getElementById('modalLikeIcon');
          const modalCount = document.getElementById('modalLikeCount');

          if (modalBtn) {
              if (isLiked) modalBtn.classList.add('liked');
              else modalBtn.classList.remove('liked');
          }
          if (modalIcon) modalIcon.className = `fa-${isLiked ? 'solid' : 'regular'} fa-heart`;
          if (modalCount) modalCount.innerText = count;
      }
  }

  function shareToLovedOne() {
      const modalTitle = document.getElementById('modalTitle').innerText;
      const shareText = `Halo! Coba lihat artikel ini: "${modalTitle}" ❤\n`;
      const url = window.location.href;

      if (navigator.share) {
          navigator.share({ title: modalTitle, text: shareText, url: url }).catch(() => {});
      } else {
          navigator.clipboard.writeText(`${shareText}${url}`);
          alert("Tautan artikel berhasil disalin!");
      }
  }

  function openPostModal(postId, title, fullBody) {
      currentActivePostId = postId;
      resetCommentForm();
      document.getElementById('modalTitle').innerText = title;
      document.getElementById('modalBody').innerHTML = fullBody;

      syncLikeUI(postId);
      syncFollowUI();

      loadModalComments(postId);
      document.getElementById('postModal').classList.add('active');
      document.body.style.overflow = 'hidden';
  }

  function loadModalComments(postId) {
      const commentsData = JSON.parse(localStorage.getItem('post_comments_data') || '{}');
      const listContainer = document.getElementById('modalCommentsList');
      listContainer.innerHTML = '';

      const list = commentsData[postId] || [];
      if (list.length === 0) {
          listContainer.innerHTML = `<div style="font-size:0.75rem; color:var(--text-sub); text-align:center;">Belum ada komentar. Jadilah yang pertama!</div>`;
          return;
      }

      list.forEach((c, idx) => {
          const item = document.createElement('div');
          item.className = 'comment-item';
          item.innerHTML = `
              <div class="comment-header">
                  <div class="comment-author">${escapeHTML(c.name)}</div>
                  <div class="comment-actions">
                      <button class="comment-action-btn" onclick="prepareEditComment(${idx})"><i class="fa-regular fa-pen-to-square"></i> Edit</button>
                      <button class="comment-action-btn" onclick="deleteComment(${idx})" style="color:#ef4444;"><i class="fa-regular fa-trash-can"></i></button>
                  </div>
              </div>
              <div class="comment-text">${escapeHTML(c.text)}</div>
              <div class="comment-time">${c.time} ${c.isEdited ? '(diedit)' : ''}</div>
          `;
          listContainer.appendChild(item);
      });
  }

  function addModalComment() {
      const nameInput = document.getElementById('commentName');
      const textInput = document.getElementById('commentText');

      const name = nameInput.value.trim() || 'Anonim';
      const text = textInput.value.trim();
      const postTitle = document.getElementById('modalTitle').innerText;

      if (!text) {
          alert("Silakan tulis isi komentar terlebih dahulu.");
          return;
      }

      let commentsData = JSON.parse(localStorage.getItem('post_comments_data') || '{}');
      if (!commentsData[currentActivePostId]) commentsData[currentActivePostId] = [];

      if (editingCommentIndex !== null) {
          commentsData[currentActivePostId][editingCommentIndex].name = name;
          commentsData[currentActivePostId][editingCommentIndex].text = text;
          commentsData[currentActivePostId][editingCommentIndex].isEdited = true;
      } else {
          const newComment = {
              name: name,
              text: text,
              time: new Date().toLocaleString(),
              isEdited: false
          };
          commentsData[currentActivePostId].unshift(newComment);
      }

      localStorage.setItem('post_comments_data', JSON.stringify(commentsData));

      if (FORMSPREE_ENDPOINT_ID && FORMSPREE_ENDPOINT_ID !== 'YOUR_FORMSPREE_ID') {
          fetch(`https://formspree.io/f/${FORMSPREE_ENDPOINT_ID}`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  'Nama Pengirim': name,
                  'Isi Komentar': text,
                  'Judul Postingan': postTitle,
                  'Waktu': new Date().toLocaleString()
              })
          }).catch(() => {});
      }

      resetCommentForm();
      loadModalComments(currentActivePostId);
      updateTotalCommentsCount();
      alert("Komentar Anda berhasil terkirim!");
  }

  function prepareEditComment(index) {
      const commentsData = JSON.parse(localStorage.getItem('post_comments_data') || '{}');
      const comment = commentsData[currentActivePostId][index];
      if (!comment) return;

      document.getElementById('commentName').value = comment.name;
      document.getElementById('commentText').value = comment.text;
      document.getElementById('commentSubmitBtn').innerText = 'Simpan Perubahan';

      editingCommentIndex = index;
  }

  function deleteComment(index) {
      if (!confirm("Apakah Anda yakin ingin menghapus komentar ini?")) return;

      let commentsData = JSON.parse(localStorage.getItem('post_comments_data') || '{}');
      if (commentsData[currentActivePostId]) {
          commentsData[currentActivePostId].splice(index, 1);
          localStorage.setItem('post_comments_data', JSON.stringify(commentsData));
      }

      if (editingCommentIndex === index) resetCommentForm();
      loadModalComments(currentActivePostId);
      updateTotalCommentsCount();
  }

  function resetCommentForm() {
      document.getElementById('commentName').value = '';
      document.getElementById('commentText').value = '';
      document.getElementById('commentSubmitBtn').innerText = 'Kirim Komentar';
      editingCommentIndex = null;
  }

  function updateTotalCommentsCount() {
      const commentsData = JSON.parse(localStorage.getItem('post_comments_data') || '{}');
      let total = 0;
      Object.keys(commentsData).forEach(k => total += commentsData[k].length);
      const el = document.getElementById('totalComments');
      if(el) el.innerText = total;
  }

  function openRecentCommentsModal() {
      closeMenu();
      loadRecentCommentsModalFeed();
      document.getElementById('recentCommentsModal').classList.add('active');
      document.body.style.overflow = 'hidden';
  }

  function closeRecentCommentsModal(e) {
      if (e.target.id === 'recentCommentsModal') closeRecentCommentsModalForce();
  }

  function closeRecentCommentsModalForce() {
      document.getElementById('recentCommentsModal').classList.remove('active');
      document.body.style.overflow = 'auto';
  }

  function loadRecentCommentsModalFeed() {
      const container = document.getElementById('recentCommentsListModal');
      if (!container) return;

      fetch('/feeds/comments/default?alt=json&max-results=10')
          .then(response => response.json())
          .then(data => {
              container.innerHTML = '';
              let recentItems = [];

              if (data.feed && data.feed.entry) {
                  data.feed.entry.forEach(entry => {
                      const author = entry.author[0].name.$t;
                      const content = entry.summary ? entry.summary.$t : (entry.content ? entry.content.$t : '');
                      const tempDiv = document.createElement('div');
                      tempDiv.innerHTML = content;
                      const cleanText = tempDiv.textContent || tempDiv.innerText || '';

                      let postTitle = 'Postingan Blog';
                      let postId = '';

                      entry.link.forEach(link => {
                          if (link.rel === 'alternate') {
                              postTitle = link.title || 'Lihat Postingan';
                              const match = link.href.match(/post-(\d+)/);
                              if (match) postId = match[1];
                          }
                      });

                      recentItems.push({
                          name: author,
                          text: cleanText.substring(0, 100) + (cleanText.length > 100 ? '...' : ''),
                          postTitle: postTitle,
                          postId: postId
                      });
                  });
              }

              const localComments = JSON.parse(localStorage.getItem('post_comments_data') || '{}');
              Object.keys(localComments).forEach(postId => {
                  const cardEl = document.querySelector(`.gallery-card[data-postid="${postId}"]`);
                  const title = cardEl ? cardEl.getAttribute('data-title') : 'Postingan Blog';

                  localComments[postId].forEach(c => {
                      recentItems.unshift({
                          name: c.name,
                          text: c.text.substring(0, 100) + (c.text.length > 100 ? '...' : ''),
                          postTitle: title,
                          postId: postId
                      });
                  });
              });

              if (recentItems.length === 0) {
                  container.innerHTML = `<div style="text-align:center; font-size:0.8rem; color:var(--text-sub); padding:20px;">Belum ada komentar terbaru.</div>`;
                  return;
              }

              recentItems.slice(0, 10).forEach(item => {
                  const commentEl = document.createElement('div');
                  commentEl.className = 'recent-dialog-item';

                  commentEl.onclick = function() {
                      triggerPostModalByComment(item.postId, item.postTitle);
                  };

                  commentEl.innerHTML = `
                      <div class="recent-dialog-author">
                          <i class="fa-regular fa-circle-user"></i> ${escapeHTML(item.name)}
                      </div>
                      <div class="recent-dialog-text">"${escapeHTML(item.text)}"</div>
                      <div class="recent-dialog-post">
                          <i class="fa-solid fa-newspaper" style="color:var(--accent-color);"></i>
                          <span>Di: <b>${escapeHTML(item.postTitle)}</b></span>
                      </div>
                  `;
                  container.appendChild(commentEl);
              });
          })
          .catch(err => {
              container.innerHTML = `<div style="text-align:center; font-size:0.8rem; color:var(--text-sub); padding:20px;">Gagal mengambil data komentar.</div>`;
          });
  }

  function triggerPostModalByComment(postId, postTitle) {
      closeRecentCommentsModalForce();

      let targetCard = document.querySelector(`.gallery-card[data-postid="${postId}"]`);

      if (!targetCard) {
          const allCards = document.querySelectorAll('.gallery-card');
          allCards.forEach(card => {
              if (card.getAttribute('data-title') === postTitle) {
                  targetCard = card;
              }
          });
      }

      if (targetCard) {
          const targetPostId = targetCard.getAttribute('data-postid');
          const title = targetCard.getAttribute('data-title');

          fetch(`/feeds/posts/default/${targetPostId}?alt=json`)
              .then(res => res.json())
              .then(data => {
                  const body = data.entry.content ? data.entry.content.$t : (data.entry.summary ? data.entry.summary.$t : '');
                  openPostModal(targetPostId, title, body);
              })
              .catch(() => {
                  openPostModal(targetPostId, title, "Isi postingan...");
              });
      } else {
          alert("Postingan tidak ditemukan.");
      }
  }

  function escapeHTML(str) {
      return str.replace(/[&<>'"]/g, 
          tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
      );
  }

  function initLikesAndStats() {
      if(!localStorage.getItem('bg_views_all')) {
          localStorage.setItem('bg_views_all', '200');
          localStorage.setItem('bg_views_today', '10');
          localStorage.setItem('bg_views_yesterday', '13');
          localStorage.setItem('bg_views_month', '55');
          localStorage.setItem('bg_views_lastmonth', '145');
          localStorage.setItem('bg_base_followers', '10');
          localStorage.setItem('bg_total_followers', '10');
      } else {
          let currentViews = parseInt(localStorage.getItem('bg_views_all')) + 1;
          let currentToday = parseInt(localStorage.getItem('bg_views_today')) + 1;
          localStorage.setItem('bg_views_all', currentViews);
          localStorage.setItem('bg_views_today', currentToday);
      }

      const viewsAll = document.getElementById('viewsAll');
      if(viewsAll) {
          viewsAll.innerText = localStorage.getItem('bg_views_all');
          document.getElementById('viewsToday').innerText = localStorage.getItem('bg_views_today');
          document.getElementById('viewsYesterday').innerText = localStorage.getItem('bg_views_yesterday');
          document.getElementById('viewsMonth').innerText = localStorage.getItem('bg_views_month');
          document.getElementById('viewsLastMonth').innerText = localStorage.getItem('bg_views_lastmonth');
          document.getElementById('totalFollowers').innerText = localStorage.getItem('bg_total_followers') || '10';
      }
  }

  function toggleAmbientAudio() {
      const audio = document.getElementById('ambientAudio');
      const status = document.getElementById('audioStatus');
      if (audio.paused) {
          audio.play();
          status.innerText = 'PLAYING';
          status.style.color = '#10b981';
      } else {
          audio.pause();
          status.innerText = 'OFF';
          status.style.color = 'var(--text-sub)';
      }
  }

  function shareProfile() {
      if (navigator.share) {
          navigator.share({ title: document.title, url: window.location.href }).catch(() => {});
      } else {
          navigator.clipboard.writeText(window.location.href);
          alert("Tautan blog berhasil disalin!");
      }
  }

  const particleIcons = { leaf: '🍃', snow: '❄️', star: '✨' };

  function setBgAnimation(type, save = true) {
      if (type !== 'none') currentAnimType = type;
      if (save && type !== 'none') localStorage.setItem('bgAnimType', type);

      clearInterval(particleInterval);
      document.querySelectorAll('.falling-particle').forEach(p => p.remove());

      if (type === 'none' || !isBubblesOn) return;

      particleInterval = setInterval(() => {
          const particle = document.createElement('div');
          particle.className = 'falling-particle';
          particle.innerText = particleIcons[type] || '✨';
          particle.style.left = Math.random() * 100 + 'vw';
          particle.style.animationDuration = (Math.random() * 3 + 2) + 's';
          particle.style.fontSize = (Math.random() * 10 + 14) + 'px';
          document.body.appendChild(particle);

          setTimeout(() => particle.remove(), 5000);
      }, particleSpeed);
  }

  function closePostModal(e) {
      if (e.target.id === 'postModal') closePostModalForce();
  }

  function closePostModalForce() {
      document.getElementById('postModal').classList.remove('active');
      document.body.style.overflow = 'auto';
  }

  const words = ["Fullstack Developer", "IT Support", "Hardware Specialist", "Content Creator"];
  let i = 0;

  function typingEffect() {
      let word = words[i].split("");
      var loopTyping = function() {
          if (word.length > 0) {
              const el = document.getElementById('typingText');
              if(el) el.innerHTML += word.shift();
          } else {
              setTimeout(deletingEffect, 2000);
              return false;
          }
          setTimeout(loopTyping, 100);
      };
      loopTyping();
  }

  function deletingEffect() {
      let word = words[i].split("");
      var loopDeleting = function() {
          if (word.length > 0) {
              word.pop();
              const el = document.getElementById('typingText');
              if(el) el.innerHTML = word.join("");
          } else {
              i = (words.length > (i + 1)) ? i + 1 : 0;
              setTimeout(typingEffect, 500);
              return false;
          }
          setTimeout(loopDeleting, 50);
      };
      loopDeleting();
  }

  typingEffect();

  function copyEmail() {
      navigator.clipboard.writeText("gandzar@gmail.com");
      alert("Email berhasil disalin!");
  }

  window.addEventListener('click', (e) => {
      const touchContainer = document.getElementById('touchContainer');
      if (!touchContainer) return;
      const ring = document.createElement('div');
      ring.className = 'touch-ring';
      ring.style.left = `${e.clientX}px`;
      ring.style.top = `${e.clientY}px`;
      touchContainer.appendChild(ring);
      setTimeout(() => ring.remove(), 700);
  });

  document.addEventListener("DOMContentLoaded", function () {
      const revealElements = document.querySelectorAll(".scroll-reveal");
      const revealObserver = new IntersectionObserver((entries, observer) => {
          entries.forEach((entry) => {
              if (entry.isIntersecting) {
                  entry.target.classList.add("revealed");
                  observer.unobserve(entry.target);
              }
          });
      }, { threshold: 0.1 });
      revealElements.forEach(el => revealObserver.observe(el));
  });
